import pytest
from hypothesis import given, assume
import hypothesis.strategies as st

from solution import cycpattern_check


# ---- reference model (obviously correct, written from spec) ----

def _naive_contains(haystack: str, needle: str) -> bool:
    # empty needle is substring of any haystack
    if needle == "":
        return True
    n, m = len(haystack), len(needle)
    if m > n:
        return False
    for i in range(n - m + 1):
        match = True
        for j in range(m):
            if haystack[i + j] != needle[j]:
                match = False
                break
        if match:
            return True
    return False


def reference(a: str, b: str) -> bool:
    if b == "":
        return _naive_contains(a, "")
    for i in range(len(b)):
        rot = b[i:] + b[:i]
        if _naive_contains(a, rot):
            return True
    return False


def all_rotations(b: str):
    if b == "":
        return [""]
    return [b[i:] + b[:i] for i in range(len(b))]


# ---- spec examples ----

@pytest.mark.parametrize("a,b,expected", [
    ("abcd", "abd", False),
    ("hello", "ell", True),
    ("whassup", "psus", False),
    ("abab", "baa", True),
    ("efef", "eeff", False),
    ("himenss", "simen", True),
])
def test_spec_examples(a, b, expected):
    assert cycpattern_check(a, b) is expected


# ---- empty / boundary ----

def test_empty_b_always_true():
    assert cycpattern_check("abc", "") is True

def test_empty_b_empty_a_true():
    assert cycpattern_check("", "") is True

def test_empty_a_nonempty_b_false():
    assert cycpattern_check("", "a") is False
    assert cycpattern_check("", "abc") is False

@given(a=st.text(alphabet="ab", max_size=5))
def test_empty_b_hypothesis(a):
    assert cycpattern_check(a, "") is True

@given(b=st.text(alphabet="ab", min_size=1, max_size=5))
def test_empty_a_nonempty_b_hypothesis(b):
    assert cycpattern_check("", b) is False

def test_single_char_in_a():
    assert cycpattern_check("hello", "e") is True
    assert cycpattern_check("hello", "z") is False
    assert cycpattern_check("", "z") is False

def test_b_equal_a_nonempty():
    assert cycpattern_check("abc", "abc") is True
    assert cycpattern_check("a", "a") is True

def test_b_longer_than_a_false():
    assert cycpattern_check("ab", "abc") is False
    assert cycpattern_check("ab", "cba") is False
    assert cycpattern_check("a", "aa") is False

@given(
    a=st.text(alphabet="abc", max_size=6),
    b=st.text(alphabet="abc", min_size=1, max_size=8),
)
def test_longer_b_implies_false(a, b):
    assume(len(b) > len(a))
    assert cycpattern_check(a, b) is False

@given(
    a=st.text(alphabet="abc", max_size=6),
    b=st.text(alphabet="abc", min_size=1, max_size=4),
)
def test_single_char_rotation_equivalence(a, b):
    # restrict to len 1: only rotation is itself, so must equal substring
    assume(len(b) == 1)
    assert cycpattern_check(a, b) is (b in a)


# ---- substring / rotation properties ----

@given(
    a=st.text(alphabet="ab", min_size=1, max_size=8),
    pre=st.integers(min_value=0, max_value=4),
    post=st.integers(min_value=0, max_value=4),
)
def test_substring_implies_true(a, pre, post):
    # b itself embedded in larger text must be found
    pad_l = "x" * pre
    pad_r = "y" * post
    big = pad_l + a + pad_r
    assert cycpattern_check(big, a) is True

@given(
    b=st.text(alphabet="ab", min_size=1, max_size=5),
    pre=st.text(alphabet="ab", max_size=3),
    post=st.text(alphabet="ab", max_size=3),
    k=st.integers(min_value=0, max_value=5),
)
def test_rotation_inserted_implies_true(b, pre, post, k):
    assume(len(b) > 0)
    rot = b[k % len(b):] + b[:k % len(b)]
    a = pre + rot + post
    assert cycpattern_check(a, b) is True

@given(
    a=st.text(alphabet="ab", max_size=6),
    b=st.text(alphabet="ab", min_size=1, max_size=5),
    k=st.integers(min_value=0, max_value=5),
)
def test_rotation_invariance_of_b(a, b, k):
    rot = b[k % len(b):] + b[:k % len(b)]
    assert cycpattern_check(a, b) == cycpattern_check(a, rot)

@given(
    a=st.text(alphabet="abc", max_size=8),
    b=st.text(alphabet="abc", max_size=5),
)
def test_equivalence_to_reference(a, b):
    assert cycpattern_check(a, b) == reference(a, b)

@given(
    a=st.text(alphabet="ab", max_size=6),
    b=st.text(alphabet="ab", min_size=1, max_size=4),
)
def test_double_rotation_identity(a, b):
    # rotating twice by i then j equals rotating once by i+j mod n
    n = len(b)
    i = 1 % n
    j = 1 % n
    r1 = b[i:] + b[:i]
    r2 = r1[j:] + r1[:j]
    rexpected = b[(i + j) % n:] + b[:(i + j) % n]
    assert r2 == rexpected
    # outcome must be consistent
    assert cycpattern_check(a, b) == cycpattern_check(a, r2)

def test_returns_bool():
    assert isinstance(cycpattern_check("hello", "ell"), bool)
    assert isinstance(cycpattern_check("abcd", "abd"), bool)
    assert isinstance(cycpattern_check("abc", ""), bool)

def test_exact_rotation_match():
    # "baa" rotations are baa, aab, aba; "abab" contains "aba"
    assert cycpattern_check("abab", "baa") is True
    # no rotation of "eeff" (eeff, effe, ffee, feef) in "efef"
    assert cycpattern_check("efef", "eeff") is False
    for rot in all_rotations("simen"):
        assert rot in "himenss" or cycpattern_check("himenss", "simen") is True
    assert cycpattern_check("himenss", "simen") is True
